import sys

sys.setrecursionlimit(1000000)

RESERVED = {"fun", "let", "rec", "in", "if", "then", "else", "true", "false"}

INT = ("int",)
BOOL = ("bool",)


def tokenize(src):
    tokens = []
    i = 0
    n = len(src)
    while i < n:
        c = src[i]
        if c in " \t\n":
            i += 1
            continue

        if "0" <= c <= "9":
            j = i
            while j < n and "0" <= src[j] <= "9":
                j += 1
            tokens.append(("int", int(src[i:j])))
            i = j
            continue

        if c.islower() or c == "_":
            j = i
            while j < n:
                d = src[j]
                if d.isalnum() or d == "_" or d == "'":
                    j += 1
                else:
                    break
            word = src[i:j]
            i = j
            if word == "true":
                tokens.append(("const", True))
            elif word == "false":
                tokens.append(("const", False))
            elif word in RESERVED:
                tokens.append(("kw", word))
            else:
                tokens.append(("id", word))
            continue

        if c == ":":
            if i + 1 < n and src[i + 1] == ":":
                tokens.append(("op", "::"))
                i += 2
            else:
                raise SyntaxError
            continue

        if c == "-":
            if i + 1 < n and src[i + 1] == ">":
                tokens.append(("arrow",))
                i += 2
            else:
                tokens.append(("op", "-"))
                i += 1
            continue

        if c == "(":
            tokens.append(("lp",))
            i += 1
            continue
        if c == ")":
            tokens.append(("rp",))
            i += 1
            continue
        if c == ",":
            tokens.append(("comma",))
            i += 1
            continue
        if c == "+":
            tokens.append(("op", "+"))
            i += 1
            continue
        if c == "*":
            tokens.append(("op", "*"))
            i += 1
            continue
        if c == "=":
            tokens.append(("op", "="))
            i += 1
            continue
        if c == "<":
            tokens.append(("op", "<"))
            i += 1
            continue
        if c == "[":
            tokens.append(("lb",))
            i += 1
            continue
        if c == "]":
            tokens.append(("rb",))
            i += 1
            continue

        raise SyntaxError


def parse(src):
    tokens = tokenize(src)
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def peek_kind():
        t = peek()
        return None if t is None else t[0]

    def consume():
        nonlocal pos
        t = tokens[pos]
        pos += 1
        return t

    def expect(kind):
        if peek_kind() != kind:
            raise SyntaxError
        return consume()

    def start_atom(tok):
        return tok is not None and tok[0] in ("int", "id", "const", "lp", "lb")

    def parse_expr_full():
        t = peek()
        if t is None:
            raise SyntaxError
        if t[0] == "kw":
            if t[1] == "fun":
                return parse_fun()
            if t[1] == "let":
                return parse_let()
            if t[1] == "if":
                return parse_if()
            raise SyntaxError
        return parse_binary(1)

    def parse_fun():
        consume()
        args = []
        while peek_kind() == "id":
            args.append(consume()[1])
        if not args:
            raise SyntaxError
        if peek_kind() != "arrow":
            raise SyntaxError
        consume()
        body = parse_expr_full()
        return ("fun", args, body)

    def parse_let():
        consume()
        if peek_kind() == "kw" and peek()[1] == "rec":
            return parse_letrec()

        if peek_kind() != "id":
            raise SyntaxError
        name = consume()[1]

        args = []
        while peek_kind() == "id":
            args.append(consume()[1])

        value = None
        if peek_kind() == "op" and peek()[1] == "=":
            consume()
            value = parse_expr_full()
        elif args:
            raise SyntaxError
        else:
            # let f x1 ... = e
            if not args:
                raise SyntaxError
            consume()  # '='
            value = parse_expr_full()

        if peek_kind() != "kw" or peek()[1] != "in":
            raise SyntaxError
        consume()
        body = parse_expr_full()

        if args:
            value = ("fun", args, value)
        return ("let", name, value, body)

    def parse_letrec():
        consume()  # 'rec'

        if peek_kind() != "id":
            raise SyntaxError
        name = consume()[1]

        args = []
        while peek_kind() == "id":
            args.append(consume()[1])
        if not args:
            raise SyntaxError

        if not (peek_kind() == "op" and peek()[1] == "="):
            raise SyntaxError
        consume()
        value = parse_expr_full()

        if peek_kind() != "kw" or peek()[1] != "in":
            raise SyntaxError
        consume()
        body = parse_expr_full()
        return ("letrec", name, args, value, body)

    def parse_if():
        consume()
        cond = parse_binary(1)
        if peek_kind() != "kw" or peek()[1] != "then":
            raise SyntaxError
        consume()
        e1 = parse_expr_full()
        if peek_kind() != "kw" or peek()[1] != "else":
            raise SyntaxError
        consume()
        e2 = parse_expr_full()
        return ("if", cond, e1, e2)

    def parse_atom():
        t = peek()
        if t is None:
            raise SyntaxError

        if t[0] == "int":
            consume()
            return ("int", t[1])
        if t[0] == "const":
            consume()
            return ("bool", t[1])
        if t[0] == "id":
            consume()
            return ("var", t[1])
        if t[0] == "lb":
            consume()
            if peek_kind() != "rb":
                raise SyntaxError
            consume()
            return ("empty_list",)
        if t[0] == "lp":
            consume()
            e1 = parse_expr_full()
            if peek_kind() == "comma":
                consume()
                e2 = parse_expr_full()
                if peek_kind() != "rp":
                    raise SyntaxError
                consume()
                return ("pair", e1, e2)
            if peek_kind() != "rp":
                raise SyntaxError
            consume()
            return e1

        raise SyntaxError

    def parse_application():
        left = parse_atom()
        while True:
            t = peek()
            if not start_atom(t):
                break
            right = parse_atom()
            left = ("app", left, right)
        return left

    BIN_PREC = {"=": 1, "<": 1, "::": 2, "+": 3, "-": 3, "*": 4}

    def parse_binary(min_prec):
        left = parse_application()
        while True:
            t = peek()
            if t is None or t[0] != "op":
                break
            prec = BIN_PREC.get(t[1])
            if prec is None or prec < min_prec:
                break

            consume()
            op = t[1]
            if op == "::":
                right = parse_binary(2)
            else:
                right = parse_binary(prec + 1)
            left = ("op", op, left, right)
        return left

    e = parse_expr_full()
    if pos != len(tokens):
        raise SyntaxError
    return e


class Subst:
    def __init__(self):
        self.m = []

    def new_var(self):
        v = len(self.m)
        self.m.append(None)
        return v


def resolve(t, subst):
    if t[0] == "var":
        v = t[1]
        r = subst.m[v]
        if r is None:
            return t
        r = resolve(r, subst)
        subst.m[v] = r
        return r
    return t


def occurs(var, t, subst):
    t = resolve(t, subst)
    if t[0] == "var":
        return t[1] == var
    if t[0] == "list":
        return occurs(var, t[1], subst)
    if t[0] == "pair":
        return occurs(var, t[1], subst) or occurs(var, t[2], subst)
    if t[0] == "func":
        return occurs(var, t[1], subst) or occurs(var, t[2], subst)
    return False


def unify(a, b, subst):
    a = resolve(a, subst)
    b = resolve(b, subst)

    if a == b:
        return

    if a[0] == "var" and b[0] == "var":
        if a[1] == b[1]:
            return
        if a[1] > b[1]:
            a, b = b, a
        subst.m[a[1]] = b
        return

    if a[0] == "var":
        if occurs(a[1], b, subst):
            raise TypeError
        subst.m[a[1]] = b
        return

    if b[0] == "var":
        if occurs(b[1], a, subst):
            raise TypeError
        subst.m[b[1]] = a
        return

    if a[0] != b[0]:
        raise TypeError

    if a[0] == "func":
        unify(a[1], b[1], subst)
        unify(a[2], b[2], subst)
        return

    if a[0] == "list":
        unify(a[1], b[1], subst)
        return

    if a[0] == "pair":
        unify(a[1], b[1], subst)
        unify(a[2], b[2], subst)
        return

    raise TypeError


def instantiate(t, subst):
    mp = {}

    def go(u):
        u = resolve(u, subst)
        if u[0] == "var":
            return u
        if u[0] == "qvar":
            v = mp.get(u[1])
            if v is None:
                v = subst.new_var()
                mp[u[1]] = v
            return ("var", v)
        if u[0] == "list":
            return ("list", go(u[1]))
        if u[0] == "pair":
            return ("pair", go(u[1]), go(u[2]))
        if u[0] == "func":
            return ("func", go(u[1]), go(u[2]))
        return u

    return go(t)


def freevars_type(t, subst, acc):
    t = resolve(t, subst)
    if t[0] == "var":
        acc.add(t[1])
        return
    if t[0] == "qvar":
        return
    if t[0] == "list":
        freevars_type(t[1], subst, acc)
        return
    if t[0] == "pair":
        freevars_type(t[1], subst, acc)
        freevars_type(t[2], subst, acc)
        return
    if t[0] == "func":
        freevars_type(t[1], subst, acc)
        freevars_type(t[2], subst, acc)
        return


def freevars_env(env, subst):
    acc = set()
    for kind, t in env.values():
        if kind == "mono":
            freevars_type(t, subst, acc)
        else:
            temp = set()
            freevars_type(t, subst, temp)
            acc |= temp
    return acc


def quantify(t, qset, subst):
    t = resolve(t, subst)
    if t[0] == "var":
        if t[1] in qset:
            return ("qvar", t[1])
        return t
    if t[0] == "qvar":
        return t
    if t[0] == "list":
        return ("list", quantify(t[1], qset, subst))
    if t[0] == "pair":
        return ("pair", quantify(t[1], qset, subst), quantify(t[2], qset, subst))
    if t[0] == "func":
        return ("func", quantify(t[1], qset, subst), quantify(t[2], qset, subst))
    return t


def generalize(env, t, subst):
    t = resolve(t, subst)
    env_free = freevars_env(env, subst)
    t_free = set()
    freevars_type(t, subst, t_free)
    qset = t_free - env_free
    return ("scheme", quantify(t, qset, subst))


def lookup(env, name):
    e = env.get(name)
    if e is None:
        raise NameError
    if e[0] == "mono":
        return e[1]
    return e[1]


def make_builtins(subst):
    q0 = ("qvar", 0)
    q1 = ("qvar", 1)

    fst = ("pair", q0, q1)
    fst_scheme = ("scheme", ("func", fst, q0))
    snd_scheme = ("scheme", ("func", fst, q1))

    l0 = ("list", q0)
    hd_scheme = ("scheme", ("func", l0, q0))
    tl_scheme = ("scheme", ("func", l0, l0))
    null_scheme = ("scheme", ("func", l0, BOOL))

    return {
        "fst": fst_scheme,
        "snd": snd_scheme,
        "hd": hd_scheme,
        "tl": tl_scheme,
        "null": null_scheme,
    }


def infer(node, env, subst):
    k = node[0]

    if k == "int":
        return INT

    if k == "bool":
        return BOOL

    if k == "empty_list":
        return ("list", subst.new_var())

    if k == "var":
        e = lookup(env, node[1])
        if e[0] == "scheme":
            return instantiate(e[1], subst)
        return resolve(e[1], subst)

    if k == "pair":
        t1 = infer(node[1], env, subst)
        t2 = infer(node[2], env, subst)
        return ("pair", t1, t2)

    if k == "app":
        ft = resolve(infer(node[1], env, subst), subst)
        at = resolve(infer(node[2], env, subst), subst)

        if ft[0] == "func":
            unify(ft[1], at, subst)
            return resolve(ft[2], subst)

        if ft[0] == "var":
            r = subst.new_var()
            unify(ft, ("func", at, r), subst)
            return resolve(r, subst)

        raise TypeError

    if k == "op":
        op = node[1]
        t1 = infer(node[2], env, subst)
        t2 = infer(node[3], env, subst)

        if op in "+*-":
            unify(t1, INT, subst)
            unify(t2, INT, subst)
            return INT

        if op == "<":
            unify(t1, INT, subst)
            unify(t2, INT, subst)
            return BOOL

        if op == "=":
            unify(t1, t2, subst)
            return BOOL

        if op == "::":
            unify(t2, ("list", t1), subst)
            return resolve(t2, subst)

        raise SyntaxError

    if k == "if":
        ct = infer(node[1], env, subst)
        unify(ct, BOOL, subst)
        t1 = infer(node[2], env, subst)
        t2 = infer(node[3], env, subst)
        unify(t1, t2, subst)
        return resolve(t1, subst)

    if k == "fun":
        _, args, body = node
        new_env = env.copy()
        for x in args:
            new_env[x] = ("mono", ("var", subst.new_var()))
        t = infer(body, new_env, subst)
        return resolve(t, subst)

    if k == "let":
        _, name, value, body = node
        t = infer(value, env, subst)
        scheme = generalize(env, t, subst)
        new_env = env.copy()
        new_env[name] = scheme
        return infer(body, new_env, subst)

    if k == "letrec":
        _, name, args, body, outer_body = node

        alpha = subst.new_var()
        rec_env = env.copy()
        rec_env[name] = ("mono", ("var", alpha))

        av = []
        for x in args:
            v = subst.new_var()
            av.append(("var", v))
            rec_env[x] = ("mono", ("var", v))

        t = infer(body, rec_env, subst)

        tf = resolve(t, subst)
        for v in reversed(av):
            tf = ("func", v, tf)

        unify(("var", alpha), tf, subst)

        scheme = generalize(env, tf, subst)
        new_env = env.copy()
        new_env[name] = scheme
        return infer(outer_body, new_env, subst)

    raise SyntaxError


def var_name(n):
    if n < 26:
        return chr(ord("a") + n)
    q = n - 26
    letter = chr(ord("a") + (q % 26))
    suffix = str(q // 26)
    return letter + suffix


def render(t, subst):
    names = {}

    def get_name(v):
        if v in names:
            return names[v]
        name = var_name(len(names))
        names[v] = name
        return "'" + name

    def fmt(u, ctx):
        u = resolve(u, subst)

        if u[0] == "var":
            return get_name(u[1])

        if u[0] == "int":
            return "int"
        if u[0] == "bool":
            return "bool"

        if u[0] == "list":
            inner = fmt(u[1], "list")
            return inner + " list"

        if u[0] == "pair":
            left = fmt(u[1], "star")
            right = fmt(u[2], "star")
            s = left + " * " + right
            if ctx == "star" or ctx == "list":
                return "(" + s + ")"
            return s

        if u[0] == "func":
            left = fmt(u[1], "arrow_left")
            right = fmt(u[2], "arrow_right")
            s = left + " -> " + right

            need = False
            if ctx == "arrow_left" or ctx == "star" or ctx == "list":
                need = True

            if need:
                return "(" + s + ")"
            return s

        raise TypeError

    return fmt(t, "")


def infer_type(src):
    ast = parse(src)

    subst = Subst()
    env = make_builtins(subst)

    t = infer(ast, env, subst)
    return render(t, subst)


def infer(src: str) -> str:
    return infer_type(src)
